{"findings":[{"tipo":"GC","causa_raiz":"No método Update(), a concatenação contínua de strings com operador '+' dentro de loops repetitivos gera centenas de objetos temporários na Heap a cada frame. Strings em C# são imutáveis; cada concatenação aloca uma nova string e descarta a anterior. Somado a isso, alocações de novos arrays de objetos ('new object[10000]') forçam a execução frequente e síncrona do Garbage Collector, causando picos de congelamento (stuttering) de mais de 23ms.","codigo_refatorado":"using System;
using System.Text;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int gcConcatIterations = 1000;
        public int gcArrayAllocs = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        private StringBuilder _sharedStringBuilder;
        private static readonly int ColorProperty = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock _propertyBlock;

        private void Awake()
        {
            _sharedStringBuilder = new StringBuilder(4096);
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                new GameObject(string.Concat("Empty_", i.ToString()));
            }

            if (overdrawLayers > 0 && overdrawMaterial != null)
            {
                BuildOverdrawLayers();
            }
        }

        private void BuildOverdrawLayers()
        {
            Camera cam = Camera.main;
            if (cam == null) return;

            float halfFov = cam.fieldOfView * 0.5f * Mathf.Deg2Rad;
            for (int i = 0; i < overdrawLayers; i++)
            {
                float d = cam.nearClipPlane + 0.05f + i * 0.001f;
                float h = 2f * d * Mathf.Tan(halfFov) * 1.1f;
                var quad = GameObject.CreatePrimitive(PrimitiveType.Quad);
                Destroy(quad.GetComponent<Collider>());
                quad.name = string.Concat("Overdraw_", i.ToString());
                quad.transform.SetParent(cam.transform, false);
                quad.transform.localPosition = new Vector3(0f, 0f, d);
                quad.transform.localScale = new Vector3(h * cam.aspect, h, 1f);
                quad.GetComponent<Renderer>().sharedMaterial = overdrawMaterial;
            }
        }

        private void Update()
        {
            if (stressGc)
            {
                _sharedStringBuilder.Clear();
                for (int i = 0; i < gcConcatIterations; i++)
                {
                    _sharedStringBuilder.Append(i);
                }
            }

            if (stressCpu)
            {
                // FindObjectsByType no Unity moderno evita a sobrecarga pesada do método antigo depreciado
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    var allObjects = UnityEngine.Object.FindObjectsByType<GameObject>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
                    GC.KeepAlive(allObjects);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    _propertyBlock.Clear();
                    _propertyBlock.SetColor(ColorProperty, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }
    }
}","explicacao_didatica":"Pense na memória RAM como uma sala de aula e no Garbage Collector (GC) como o faxineiro. Toda vez que você usa texto com o sinal de soma (+) ou cria arrays descartáveis dentro do Update(), você está amassando papéis e jogando no chão 60 vezes por segundo. Quando o chão fica lotado, o faxineiro precisa congelar o jogo inteiro para varrer tudo (causando travamentos de 23 milissegundos). Usando StringBuilder reutilizável e MaterialPropertyBlock, nós paramos de jogar papéis no chão, permitindo que a taxa de quadros fique lisa e sem engasgos."},{"tipo":"CPU","causa_raiz":"A chamada 'FindObjectsOfType<GameObject>()' dentro de um loop no Update() varre iterativamente a hierarquia de toda a cena em busca de todos os GameObjects existentes, gerando um custo computacional desastroso na CPU de até 118ms por frame e alocando arrays no GC.","codigo_refatorado":"using System;
using System.Collections.Generic;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        public bool stressGc = false;
        public bool stressCpu = false;
        public bool stressDraw = false;
        public GameObject testPrefab;

        [Range(1, 20)]
        public float spawnRadius = 10f;
        [Range(1, 50)]
        public int cubesPerFrame = 1;
        public bool useUniqueMaterials = false;
        [Range(1, 512)]
        public int cpuScansPerFrame = 1;
        public int emptyObjects = 0;
        public int overdrawLayers = 0;
        public Material overdrawMaterial;
        [Range(0, 2000)]
        public int prepopulateCount = 0;

        // Cache estatico para evitar varredura em tempo real pela hierarquia
        private static readonly List<GameObject> RegisteredObjects = new List<GameObject>(2048);
        private static readonly int ColorProperty = Shader.PropertyToID("_Color");
        private MaterialPropertyBlock _propertyBlock;

        private void Awake()
        {
            _propertyBlock = new MaterialPropertyBlock();
        }

        private void Start()
        {
            if (prepopulateCount > 0 && testPrefab != null)
            {
                for (int i = 0; i < prepopulateCount; i++)
                {
                    SpawnOne();
                }
            }

            for (int i = 0; i < emptyObjects; i++)
            {
                var go = new GameObject(string.Concat("Empty_", i.ToString()));
                RegisteredObjects.Add(go);
            }
        }

        private void Update()
        {
            if (stressCpu)
            {
                // Em vez de FindObjectsOfType na cena inteira, acessa diretamente a colecao em cache
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    int count = RegisteredObjects.Count;
                    GC.KeepAlive(count);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++)
                {
                    SpawnOne();
                }
            }
        }

        private void SpawnOne()
        {
            var clone = Instantiate(testPrefab, UnityEngine.Random.insideUnitSphere * spawnRadius, Quaternion.identity);
            RegisteredObjects.Add(clone);

            if (useUniqueMaterials)
            {
                var renderer = clone.GetComponent<Renderer>();
                if (renderer != null)
                {
                    _propertyBlock.Clear();
                    _propertyBlock.SetColor(ColorProperty, new Color(UnityEngine.Random.value, UnityEngine.Random.value, UnityEngine.Random.value));
                    renderer.SetPropertyBlock(_propertyBlock);
                }
            }
        }

        private void OnDestroy()
        {
            RegisteredObjects.Clear();
        }
    }
}","explicacao_didatica":"Executar FindObjectsOfType todo frame é como entrar em uma biblioteca enorme e ler a capa de todos os livros da sala para achar os itens, repetindo isso 60 vezes por segundo. O correto é manter uma lista cadastral (cache): quando um objeto novo nasce (Start ou Instantiate), nós apenas o anotamos na lista; assim a CPU consulta a lista instantaneamente sem precisar vasculhar a cena inteira."}],"dicas_level_design":null}

